// n fused chain iterations for two lanes, in place. The loop lives in the
// asm: intermediate digests never touch memory (ASCII W-slot back-edge).
TEXT ·pairHashHexN(SB), NOSPLIT, $96-24
	MOVQ    pa+0(FP), SI
	MOVQ    pb+8(FP), R9
	MOVQ    n+16(FP), CX
	TESTQ   CX, CX
	JG      pairN_start
	RET

pairN_start:
	VMOVDQA flip_mask<>+0(SB), X14
	LEAQ    K256<>+0(SB), AX
