	// shuffled IV -> (SP),16(SP); reloaded at every loop head
	VMOVDQU iv_words<>+0(SB), X1
	VMOVDQU iv_words<>+16(SB), X2
	PSHUFD  $0xb1, X1, X1
	PSHUFD  $0x1b, X2, X2
	VMOVDQA X1, X7
