	// lane A: load 64 bytes, flip to message form in W slots
	VMOVDQU (SI), X3
	VMOVDQU 16(SI), X4
	VMOVDQU 32(SI), X5
	VMOVDQU 48(SI), X6
	PSHUFB  X14, X3
	PSHUFB  X14, X4
	PSHUFB  X14, X5
	PSHUFB  X14, X6
	// lane B: load 64 bytes, flip to message form in W slots
